    "start_state": {
      "location": "ResidentialDiningRoom",
      "subject": "小安刚拖行李箱进入餐厅入口，林阿姨已坐在餐桌旁",
      "action_phase": "setup：雨夜归家，门口犹豫与母亲放杯示意",
      "camera": "固定宽幅镜头，同时容纳入口与餐桌",
      "screen_direction": "入口在左，餐桌在右，两人横向相对",
      "pose_and_gaze": "小安站在门框内攥着拉杆，目光局促地望向餐桌；林阿姨坐在餐椅上抬眼看向门口",
      "prop_state": "黑色硬壳行李箱停在小安脚边，盛有温水的玻璃杯原本在林阿姨手边",
      "open_motion": "小安拖行李箱停步后未继续向前，林阿姨正抬眼望向她并准备拿杯",
      "lighting": "暖黄壁灯与雨夜冷窗光混合"
    },
    "end_state": {
      "location": "ResidentialDiningRoom",
      "subject": "小安仍在门口，林阿姨已将玻璃杯放到空椅旁",
      "action_phase": "setup完成，等待小安走近落座",
      "camera": "固定宽幅镜头",
      "screen_direction": "入口在左，餐桌在右",
      "pose_and_gaze": "小安站在原地，视线落向空椅旁的玻璃杯；林阿姨坐姿平和，目光停在小安身上",
      "prop_state": "黑色硬壳行李箱仍在小安脚边，盛有温水的玻璃杯稳放在空椅旁桌面",
      "open_motion": "小安尚未迈步，下一镜将放下行李走向桌边",
      "lighting": "暖黄壁灯与雨夜冷窗光混合"
    },
    "story_change": "小安雨夜归家在餐厅门口犹豫，林阿姨看见她后没有起身迎上，而是将一杯温水轻轻放到空椅旁的桌面，用熟悉的日常动作消解久别生疏。",
    "story_state_after": "两人尚未同桌落座，小安仍站在门口，玻璃杯已在空椅旁等待，下一镜小安将放下行李走向桌边。",
    "action_plan": {
      "first": {
        "actor": "XiaoAn",
        "action": "拖着黑色硬壳滚轮行李箱从餐厅入口木质门框走入，在门槛内一步处停住，手指攥住行李箱拉杆，目光望向餐桌方向又短暂垂下，显露出久别归家的局促与犹豫。",
        "result": "小安站在餐厅入口内侧，行李箱停在脚边，身体朝向餐桌却未再向前迈步。",
        "kind": "transition",
        "target": "黑色硬壳滚轮行李箱",
        "weight": 2.5
      },
      "following": [
        {
          "actor": "LinAyi",
          "action": "坐在餐椅上的林阿姨抬眼看见门口的小安，没有起身，只伸手拿起桌边盛有温水的透明玻璃杯，轻轻放到靠近空椅的桌面边缘。",
          "result": "玻璃杯稳放在空椅旁的桌面，林阿姨收回手，目光仍停在小安身上，没有催促。",
          "kind": "interaction",
          "target": "盛有温水的透明玻璃杯",
          "effect": {
            "mode": "direct_contact",
            "motion": "static",
            "source": "LinAyi",
            "region": "长方形木质餐桌靠近空椅一侧的桌面",
            "unaffected": "餐厅入口、小安脚边的行李箱与临街玻璃窗"
          },
          "response": "impact",
          "link_previous": true,
          "resolution": {
            "states": {
              "LinAyi": [
                {
                  "state": "坐在餐椅上，目光温和望向门口的小安，手已从玻璃杯收回"
                }
              ],
              "XiaoAn": [
                {
                  "state": "站在餐厅入口内侧，行李箱停在脚边，神色局促犹豫"
                }
              ],
              "盛有温水的透明玻璃杯": [
                {
                  "state": "稳放在靠近空椅的桌面边缘，杯内温水未洒"
                }
              ]
            }
          },
          "overlap": false,
          "weight": 2.5
        },
        {
          "actor": "LinAyi",
          "action": "保持坐姿与温和目光，不迎上去也不说话，等待小安自己走近。",
          "result": "两人隔着餐桌与入口的距离安静对视，小安的视线落向空椅旁的玻璃杯，脚步仍停在原地。",
          "kind": "hold",
